using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // (non-deterministic seed data causes spurious migrations).
        // Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking-change fixes ---
class CosmosDbContext : DbContext
{
    public DbSet<Customer> Customers => Set<Customer>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 renamed the discriminator property
        // from "Discriminator" to "$type". Existing documents still use "Discriminator".
        // Fix: explicitly configure the old property name to avoid data mismatch.
        modelBuilder.Entity<Customer>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Customer>().ToContainer("Customers");
    }
}

class Customer
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}

// --- Cosmos query service demonstrating sync-to-async fix ---
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BREAKING CHANGE 2: EF Core 9 Cosmos provider removed synchronous query
    // support. Calls like .ToList(), .First(), .Count() now throw
    // InvalidOperationException.
    // Fix: convert all sync LINQ queries to async equivalents.
    public async Task<List<Customer>> GetCustomersAsync()
        => await _db.Customers.ToListAsync();

    public async Task<Customer?> GetCustomerAsync(string name)
        => await _db.Customers.FirstOrDefaultAsync(c => c.Name == name);

    public async Task<int> CountCustomersAsync()
        => await _db.Customers.CountAsync();
}

