arguments.new_str:
using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // BREAKING CHANGE 3: EF Core 9 throws if Migrate() is called inside a
    // user-managed transaction (migrations manage their own transactions).
    // Fix: remove the outer BeginTransaction/Commit wrapper.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

